import sys
from playwright.sync_api import sync_playwright
STUB=open('/home/claude/work/tests-front/stub_finance.js',encoding='utf8').read()
res=[]
def check(n,c): res.append(bool(c)); print(('PASS ' if c else 'FAIL ')+n)
with sync_playwright() as p:
    b=p.chromium.launch(); errs=[]
    def new(pre="",w=1200):
        pg=b.new_page(viewport={'width':w,'height':1000},locale='fr-FR'); pg.on("pageerror",lambda e:errs.append(str(e)))
        pg.on("dialog",lambda d:d.accept()); pg.route("**/cdn.jsdelivr.net/**",lambda r:r.abort()); pg.add_init_script(pre+STUB); pg.goto("http://localhost:8765/admin-paiements.html"); pg.wait_for_timeout(1000); return pg
    n=new()
    check("non-admin : accès refusé, panneau masqué", "refusé" in n.inner_text("#state").lower() and n.is_hidden("#panel"))
    a=new("window.__ADMIN=true;")
    check("dépôts : 2 lignes avec référence interne, prestataire, statut", a.locator("#t-dep tbody tr").count()==2 and "DEP-AAAAAAAAAAAAAAAA" in a.inner_text("#t-dep") and "flutterwave" in a.inner_text("#t-dep") and "99" in a.inner_text("#t-dep"))
    check("dépôts : « Confirmer » seulement pour un virement en attente", a.locator("[data-confirm]").count()==1)
    a.click('[data-detail="d2"]'); a.wait_for_timeout(200)
    check("détails prestataire affichés, HTML non interprété", "successful" in a.inner_text("#dep-json") and a.evaluate("window.__xss")==None and a.locator("#dep-json img").count()==0)
    a.click('[data-confirm="d1"]'); a.fill("#dc-bank","VIR"); a.fill("#dc-amount","10000"); a.click('#dep-confirm button[type=submit]'); a.wait_for_timeout(300)
    check("virement : référence bancaire trop courte refusée", "référence du virement" in a.inner_text("#dc-err").lower() and a.evaluate("window.__db.deposits[0].status")=="pending")
    a.fill("#dc-bank","VIR-2026-1188"); a.fill("#dc-amount","9000"); a.click('#dep-confirm button[type=submit]'); a.wait_for_timeout(300)
    check("virement : montant différent de celui du dépôt => crédit refusé", "ne correspond pas" in a.inner_text("#dc-err") and a.evaluate("window.__db.deposits[0].status")=="pending")
    a.fill("#dc-amount","10000"); a.click('#dep-confirm button[type=submit]'); a.wait_for_timeout(500)
    check("virement : montant exact => crédité, référence enregistrée", a.evaluate("window.__db.deposits[0].status")=="confirmed" and a.evaluate("window.__db.deposits[0].provider_ref")=="bank:VIR-2026-1188")
    a.click('[data-sec="wd"]'); a.wait_for_timeout(200)
    check("retraits : destination complète, frais et net visibles", "+2250700000001" in a.inner_text("#t-wd") and "Net" in a.inner_text("#t-wd"))
    check("retraits : destination échappée", a.locator("#t-wd b").count()==0)
    a.click('[data-wd="11111111-1111-1111-1111-111111111111"]'); a.wait_for_timeout(200)
    a.click('[data-do="reject_withdrawal"]'); a.wait_for_timeout(300)
    check("refus sans motif : bloqué", "motif" in a.inner_text("#wa-err").lower() and a.evaluate("window.__db.withdrawals[0].status")=="requested")
    a.click('[data-do="approve_withdrawal"]'); a.wait_for_timeout(500)
    check("approbation enregistrée", a.evaluate("window.__db.withdrawals[0].status")=="approved")
    a.click('[data-wd="11111111-1111-1111-1111-111111111111"]'); a.wait_for_timeout(200); a.click('[data-do="pay_manual"]'); a.wait_for_timeout(300)
    check("payé manuellement sans référence réelle : bloqué", "référence réelle" in a.inner_text("#wa-err").lower() and a.evaluate("window.__db.withdrawals[0].status")=="approved")
    a.click('[data-do="pay_auto"]'); a.wait_for_timeout(500)
    check("paiement automatique : message d'attente de confirmation, statut inchangé", "dès confirmation" in a.inner_text("#msg") and a.evaluate("window.__db.withdrawals[0].status")=="approved")
    a.click('[data-wd="22222222-2222-2222-2222-222222222222"]'); a.wait_for_timeout(200); a.click('[data-do="pay_auto"]'); a.wait_for_timeout(300)
    check("paiement automatique vers un compte bancaire : refusé avec explication", "mobile money" in a.inner_text("#wa-err"))
    a.fill("#wa-input","VIR-OUT-5521"); a.click('[data-do="pay_manual"]'); a.wait_for_timeout(500)
    check("payé manuellement avec référence : statut payé", a.evaluate("window.__db.withdrawals[1].status")=="paid")
    a.click('[data-sec="set"]'); a.wait_for_timeout(200)
    check("réglages : moyens actuels reflétés (Wave et virement cochés)", a.is_checked('[data-m="wave"]') and a.is_checked('[data-m="bank_transfer"]') and not a.is_checked('[data-m="card"]'))
    a.check('[data-m="orange_money"]'); a.fill("#s-pct","1,5"); a.fill("#s-fmin","150"); a.click('#set-form button[type=submit]'); a.wait_for_timeout(500)
    st={s["key"]:s["value"] for s in a.evaluate("window.__db.platform_settings")}
    check("réglages enregistrés (moyen activé, frais 1,5 % min 150)", st["payment_methods"]["orange_money"]==True and st["withdraw_fee"]=={"percent":1.5,"min":150} and "enregistrés" in a.inner_text("#set-msg"))
    a.fill("#s-pct","99"); a.click('#set-form button[type=submit]'); a.wait_for_timeout(300)
    check("réglages : pourcentage absurde refusé", "invalides" in a.inner_text("#set-msg") and a.evaluate("window.__db.platform_settings.find(s=>s.key==='withdraw_fee').value.percent")==1.5)
    check("réglages : aucun champ de clé secrète", a.locator('#set-form input[type=password]').count()==0 and "secret" not in a.input_value("#b-bic").lower())
    a.click('[data-sec="aud"]'); a.wait_for_timeout(200)
    check("journal d'audit affiché", "deposit_confirmed" in a.inner_text("#t-aud"))
    m=new("window.__ADMIN=true;",390)
    check("mobile : pas de défilement horizontal", m.evaluate("document.documentElement.scrollWidth<=window.innerWidth+1"))
    print("ERREURS:",sorted(set(errs)))
    check("aucune erreur JS propre (hors CDN)", not [x for x in errs if 'gsap' not in x.lower() and 'ScrollTrigger' not in x])
    b.close()
print(f"{sum(res)}/{len(res)} OK"); sys.exit(0 if all(res) else 1)
